    ["Continue ahead in ^The Forgotten Pool^ until you reach ^Guardian of the Deep^."] = "Continúa recto por ^The Forgotten Pool^ hasta llegar a ^Guardian of the Deep^.",
    ["Continue ahead into the main courtyard to find ^Spellblade Aluriel^."] = "Avanza hasta el patio principal para encontrar a ^Spellblade Aluriel^.",
