    ["Continue along the path until you reach a room with Ethereal enemies, and take the ramp up."] = "Sigue por el camino hasta llegar a una sala con enemigos etéreos y sube por la rampa.",
    ["Continue backtracking through this room."] = "Sigue retrocediendo por esta sala.",
    ["Continue backtracking to main concourse. When you reach it, cut through the platform and take the northeast path out of this room."] = "Sigue retrocediendo hasta la sala principal. Cuando llegues, cruza la plataforma y toma el camino noreste para salir de esta sala.",
    ["Continue climbing"] = "Sigue subiendo",
    ["Continue climbing."] = "Sigue subiendo.",
    ["Continue down the path and clear the trash to spawn ^The Amalgamation Chamber^."] = "Continúa bajando por el camino y elimina a los enemigos para hacer aparecer a ^The Amalgamation Chamber^.",
    ["Continue down the stairs until you reach the room with ^Archaedas^. Activate the ^Altar of Archaedas^ to begin the fight."] = "Baja las escaleras hasta llegar a la sala de ^Archaedas^. Activa ^Altar of Archaedas^ para iniciar el combate.",
    ["Continue down the stairs, and follow the linear path to the south side of the map. Jump down to engage ^Gekkan^."] = "Baja las escaleras y sigue el camino lineal hasta el lado sur del mapa. Salta para enfrentarte a ^Gekkan^.",
    ["Continue down the stairs, following the path until you reach ^Sisters of the Moon^."] = "Sigue bajando las escaleras por el camino hasta ^Sisters of the Moon^.",
    ["Continue following the linear path into the next room."] = "Sigue el camino lineal hasta la siguiente sala.",
    ["Continue following the path ahead to reach ^Sennarth^."] = "Sigue el camino de frente hasta ^Sennarth^.",
