    -- Naxxramas: route notes, solo tips, and display names.
    ["After defeating ^Anub'Rekhan^, backtrack out of his room and take a left. Stay to the left while following the path to ^Grand Widow Faerlina^."] = "Tras derrotar a ^Anub'Rekhan^, retrocede para salir de su sala y gira a la izquierda. Mantente a la izquierda mientras sigues el camino hasta ^Grand Widow Faerlina^.",
    ["After defeating ^Faerlina^, head southeast and follow the path back north all the way to ^Maexxna^."] = "Tras derrotar a ^Faerlina^, ve hacia el sureste y sigue el camino de vuelta hacia el norte hasta ^Maexxna^.",
    ["After defeating ^Gothik the Harvester^, take the south exit and follow the path around to reach ^The Four Horsemen^."] = "Tras derrotar a ^Gothik the Harvester^, toma la salida sur y sigue el camino hasta ^The Four Horsemen^.",
    ["After defeating ^Grobbulus^, exit south from the top of the room. Walk across a pipe as you follow the path around to find ^Gluth^."] = "Tras derrotar a ^Grobbulus^, sal por el lado sur de la parte superior de la sala. Cruza una tubería mientras sigues el camino hasta ^Gluth^.",
    ["After defeating ^Heigan^, exit to the east and follow the path around to ^Loatheb^."] = "Tras derrotar a ^Heigan^, sal hacia el este y sigue el camino hasta ^Loatheb^.",
    ["After defeating ^Noth^, exit to the east and follow the path around to ^Heigan the Unclean^."] = "Tras derrotar a ^Noth^, sal hacia el este y sigue el camino hasta ^Heigan the Unclean^.",
    ["After defeating ^Razuvious^, take the south exit and follow the path around to reach ^Gothik the Harvester^. Tag him to start the encounter."] = "Tras derrotar a ^Razuvious^, toma la salida sur y sigue el camino hasta ^Gothik the Harvester^. Atácalo para iniciar el encuentro.",
    ["After defeating ^Thaddius^, click the ^Naxxramas Portal^."] = "Tras derrotar a ^Thaddius^, haz clic en el ^Naxxramas Portal^.",
    ["After defeating ^The Four Horsemen^, click the ^Naxxramas Portal^ to be teleported back to the entrance."] = "Tras derrotar a ^The Four Horsemen^, haz clic en el ^Naxxramas Portal^ para volver a la entrada.",
    ["After killing ^Gluth^, follow the path straight ahead to reach ^Thaddius^."] = "Tras matar a ^Gluth^, sigue el camino recto hasta ^Thaddius^.",
    ["After killing ^Loatheb^, click on the ^Naxxramas Portal^ to be teleported back to the entrance."] = "Tras matar a ^Loatheb^, haz clic en el ^Naxxramas Portal^ para volver a la entrada.",
    ["After killing ^Maexxna^, click the ^Naxxramas Portal^ to return to the entrance."] = "Tras matar a ^Maexxna^, haz clic en el ^Naxxramas Portal^ para volver a la entrada.",
    ["After killing ^Patchwerk^, follow the path and take a right to reach ^Grobbulus^."] = "Tras matar a ^Patchwerk^, sigue el camino y gira a la derecha para llegar a ^Grobbulus^.",
    ["After killing ^Sapphiron^, take the west exit and follow the path around to ^Kel'Thuzad^. Walk into the middle circle to begin the encounter."] = "Tras matar a ^Sapphiron^, toma la salida oeste y sigue el camino hasta ^Kel'Thuzad^. Entra en el círculo central para iniciar el encuentro.",
    ["After returning to the entrance, take the southeast path towards ^The Plague Quarter^."] = "Tras volver a la entrada, toma el camino sureste hacia ^The Plague Quarter^.",
    ["After teleporting to ^Sapphiron's Lair^, proceed ahead to engage ^Sapphiron^."] = "Tras teletransportarte a ^Sapphiron's Lair^, sigue recto para enfrentarte a ^Sapphiron^.",
    ["After teleporting, click the ^Orb of Naxxramas^ right next to you."] = "Tras teletransportarte, haz clic en el ^Orb of Naxxramas^ que tienes al lado.",
    ["After teleporting, take the northwest exit toward ^The Construct Quarter^."] = "Tras teletransportarte, toma la salida noroeste hacia ^The Construct Quarter^.",
    ["After teleporting, take the southwest path towards ^The Military Quarter^."] = "Tras teletransportarte, toma el camino suroeste hacia ^The Military Quarter^.",
    ["After zoning in, take the northeast path to ^The Arachnid Quarter^."] = "Al entrar, toma el camino noreste hacia ^The Arachnid Quarter^.",
